// The domain defines the port; the store provides the adapter.
// Dependencies point inward — the domain imports neither
// net/http nor database/sql, so the context stays independent.
package order

import "context"

// Repository is the PORT the domain depends on.
type Repository interface {
	Save(ctx context.Context, o Order) error
	Get(ctx context.Context, id string) (Order, error)
}

type Service struct{ repo Repository } // holds the interface, not *sql.DB

func (s *Service) Fetch(ctx context.Context, id string) (Order, error) {
	if id == "" {
		return Order{}, errors.New("empty id")
	}
	return s.repo.Get(ctx, id) // domain only knows the port
}
